// ---------------------------------------------------------------------------
// Safe rule evaluator for POST /check
//
// NOTE: docs/RULES_ENGINE.md proposes using `Function(...)` to evaluate
// caller-supplied expressions. That is a remote code execution vulnerability:
// any client posting to /check could read files, env vars, or make outbound
// network calls from the server process. This implementation deliberately
// rejects that approach and instead parses a restricted expression language
// covering the documented use case (comparisons / boolean logic over a
// context object), e.g.  `ctx.amount > 100 && ctx.country == "US"`.
// ---------------------------------------------------------------------------

function tokenize(src) {
  const tokens = [];
  const re =
    /\s+|(&&|\|\||==|!=|<=|>=|<|>|!|\(|\)|,|\.)|("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')|(-?\d+(?:\.\d+)?)|([A-Za-z_][A-Za-z0-9_]*)/g;
  let m;
  let lastIndex = 0;
  while ((m = re.exec(src)) !== null) {
    if (m.index !== lastIndex) {
      throw new Error(`Unexpected character at ${lastIndex}`);
    }
    lastIndex = re.lastIndex;
    if (m[0].trim() === '') continue;
    if (m[1]) tokens.push({ type: 'op', value: m[1] });
    else if (m[2]) tokens.push({ type: 'str', value: JSON.parse(m[2].replace(/^'|'$/g, '"')) });
    else if (m[3]) tokens.push({ type: 'num', value: Number(m[3]) });
    else if (m[4]) {
      const v = m[4];
      if (v === 'true') tokens.push({ type: 'bool', value: true });
      else if (v === 'false') tokens.push({ type: 'bool', value: false });
      else if (v === 'null') tokens.push({ type: 'null', value: null });
      else tokens.push({ type: 'ident', value: v });
    }
  }
  if (lastIndex !== src.length) throw new Error(`Unexpected trailing input at ${lastIndex}`);
  return tokens;
}

// Recursive-descent parser:
//   or     := and ('||' and)*
//   and    := eq  ('&&' eq)*
//   eq     := cmp (('=='|'!=') cmp)*
//   cmp    := unary (('<'|'<='|'>'|'>=') unary)*
//   unary  := '!' unary | primary
//   primary:= literal | path | '(' or ')'
//   path   := ident ('.' ident)*
function parse(tokens) {
  let i = 0;
  const peek = () => tokens[i];
  const eat = (type, value) => {
    const t = tokens[i];
    if (!t || t.type !== type || (value !== undefined && t.value !== value)) {
      throw new Error(`Parse error at token ${i}`);
    }
    i++;
    return t;
  };

  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().type === 'op' && peek().value === '||') {
      i++;
      left = { kind: 'or', left, right: parseAnd() };
    }
    return left;
  }
  function parseAnd() {
    let left = parseEq();
    while (peek() && peek().type === 'op' && peek().value === '&&') {
      i++;
      left = { kind: 'and', left, right: parseEq() };
    }
    return left;
  }
  function parseEq() {
    let left = parseCmp();
    while (peek() && peek().type === 'op' && (peek().value === '==' || peek().value === '!=')) {
      const op = tokens[i++].value;
      left = { kind: 'binop', op, left, right: parseCmp() };
    }
    return left;
  }
  function parseCmp() {
    let left = parseUnary();
    while (
      peek() &&
      peek().type === 'op' &&
      ['<', '<=', '>', '>='].includes(peek().value)
    ) {
      const op = tokens[i++].value;
      left = { kind: 'binop', op, left, right: parseUnary() };
    }
    return left;
  }
  function parseUnary() {
    if (peek() && peek().type === 'op' && peek().value === '!') {
      i++;
      return { kind: 'not', expr: parseUnary() };
    }
    return parsePrimary();
  }
  function parsePrimary() {
    const t = peek();
    if (!t) throw new Error('Unexpected end of expression');
    if (t.type === 'op' && t.value === '(') {
      i++;
      const e = parseOr();
      eat('op', ')');
      return e;
    }
    if (t.type === 'num' || t.type === 'str' || t.type === 'bool' || t.type === 'null') {
      i++;
      return { kind: 'lit', value: t.value };
    }
    if (t.type === 'ident') {
      const path = [tokens[i++].value];
      while (peek() && peek().type === 'op' && peek().value === '.') {
        i++;
        path.push(eat('ident').value);
      }
      return { kind: 'path', path };
    }
    throw new Error(`Unexpected token ${JSON.stringify(t)}`);
  }

  const ast = parseOr();
  if (i !== tokens.length) throw new Error('Trailing tokens after expression');
  return ast;
}

function evaluate(node, env) {
  switch (node.kind) {
    case 'lit':
      return node.value;
    case 'path': {
      // Only `ctx.<...>` paths are allowed. No access to `req`, globals, etc.
      if (node.path[0] !== 'ctx') {
        throw new Error(`Unknown identifier '${node.path[0]}'`);
      }
      let cur = env.ctx;
      for (let k = 1; k < node.path.length; k++) {
        if (cur == null) return undefined;
        // Block access to prototype chain / dangerous keys.
        const key = node.path[k];
        if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
          throw new Error(`Forbidden property '${key}'`);
        }
        if (!Object.prototype.hasOwnProperty.call(cur, key)) return undefined;
        cur = cur[key];
      }
      return cur;
    }
    case 'not':
      return !evaluate(node.expr, env);
    case 'and':
      return evaluate(node.left, env) && evaluate(node.right, env);
    case 'or':
      return evaluate(node.left, env) || evaluate(node.right, env);
    case 'binop': {
      const l = evaluate(node.left, env);
      const r = evaluate(node.right, env);
      switch (node.op) {
        case '==': return l === r;
        case '!=': return l !== r;
        case '<':  return l <   r;
        case '<=': return l <=  r;
        case '>':  return l >   r;
        case '>=': return l >=  r;
      }
      throw new Error(`Unknown operator ${node.op}`);
    }
  }
  throw new Error(`Unknown node kind ${node.kind}`);
}

