//
// NOTE: docs/RULES_ENGINE.md proposes evaluating caller-supplied JS via the
// `Function` constructor. That is a remote code execution sink: any client
// could read process.env, the filesystem, or make outbound requests. We do
// NOT implement that. Instead we evaluate a small JSON predicate DSL.
//
// Rule grammar:
//   Rule       := { "op": Op, ... }
//   Logical    := { "op": "and"|"or", "rules": [Rule, ...] }
//                | { "op": "not", "rule": Rule }
//   Comparison := { "op": "=="|"!="|">"|">="|"<"|"<="|"in",
//                   "field": "dotted.path", "value": <literal> }
//
// `field` is resolved against the request context only. No function calls,
// no property access on prototypes, no globals.

const COMPARATORS = {
  '==': (a, b) => a === b,
  '!=': (a, b) => a !== b,
  '>':  (a, b) => typeof a === 'number' && typeof b === 'number' && a > b,
  '>=': (a, b) => typeof a === 'number' && typeof b === 'number' && a >= b,
  '<':  (a, b) => typeof a === 'number' && typeof b === 'number' && a < b,
  '<=': (a, b) => typeof a === 'number' && typeof b === 'number' && a <= b,
  'in': (a, b) => Array.isArray(b) && b.includes(a),
};

const UNSAFE_KEYS = new Set(['__proto__', 'prototype', 'constructor']);

function getField(ctx, path) {
  if (typeof path !== 'string' || path.length === 0) return undefined;
  let cur = ctx;
  for (const part of path.split('.')) {
    if (cur === null || typeof cur !== 'object') return undefined;
    if (UNSAFE_KEYS.has(part)) return undefined;
    if (!Object.prototype.hasOwnProperty.call(cur, part)) return undefined;
    cur = cur[part];
  }
  return cur;
